// Verus solution for forming maximum number of teams of 3 eligible participants.
//
// Eligibility rule: a participant with attendance `a` is eligible iff 5 - a >= k.
// We consider only the first `min(n, participations.len())` participants.
// Answer = (#eligible) / 3.

use vstd::prelude::*;

verus! {

spec fn eligible(a: int, k: int) -> bool {
    0 <= a <= 5 && 0 <= k <= 5 && 5 - a >= k
}

spec fn count_eligible(participations: Seq<int>, k: int) -> int
    recommends 0 <= k <= 5
{
    participations.filter(|a: int| eligible(a, k)).len() as int
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> (res: u8)
    requires
        // Per problem statement.
        k <= 5,
        forall|i: int| 0 <= i < participations@.len() ==> participations@[i] <= 5,
    ensures
        // res is the maximum number of disjoint teams of 3 eligible participants
        // among the first min(n, len) elements.
        res as int
            == (count_eligible(
                    participations@.take(if (n as int) <= participations@.len() { n as int } else { participations@.len() })
                        .map(|x: u8| x as int),
                    k as int)
                / 3),
{
    let limit: usize = if (n as usize) <= participations.len() { n as usize } else { participations.len() };

    let mut i: usize = 0;
    let mut elig: u8 = 0;

    while i < limit
        invariant
            i <= limit,
            limit <= participations.len(),
            elig as int
                == count_eligible(
                    participations@.subrange(0, i as int).map(|x: u8| x as int),
                    k as int),
    {
        let a = participations[i];
        if 5u8 - a >= k {
            elig = elig + 1;
        }
        i = i + 1;
    }

    // Integer division rounds down, which matches "max # of disjoint teams of size 3".
    res = elig / 3;
}

} // verus!